INSERT INTO stories (id, title, body, original_body, date, place, created_at) VALUES ('844b9230-48fb-4d7e-88df-24f4cadcfd81', 'The main branches of the family', 'Told by Mohammad Darabi, sixth generation.

The principal branches of the family, the ones that set its main lines, are the children of Mohammad Zehtab (Darabi). Their names in order of age are Hossein, Fatemeh, Ramazan, Ghassem and Abbas. The last of them died in his youth.

A short account of each is given below.', 'سرشاخه ها
نقل از آقاى محمد دارابی نسل ششم
سر شاخه هاى فاميل كه نقش محورى را تعين مى كنند ، فرزندان محمد زهتاب (دارابى) مى باشند اسامى آنها بترتيب سن عبارتست از حسين، فاطمه، رمضان ، قاسم وعباس ، نفر آخر در نوجوانى فوت مى كند، 
اينك مختصرى از هر كدام در زير باطلاع مىرسد
.', NULL, NULL, '2026-08-27T08:32:46.753Z');
INSERT OR IGNORE INTO story_people (story_id, person_id) VALUES ('844b9230-48fb-4d7e-88df-24f4cadcfd81', 'c8a1f8a4-d83d-4638-8de4-ceb8246908cb');
