INSERT OR IGNORE INTO story_people (story_id, person_id) VALUES ('844b9230-48fb-4d7e-88df-24f4cadcfd81', '9b32dea9-8c7c-41a1-9aa5-552816721199');
INSERT INTO stories (id, title, body, original_body, date, place, created_at) VALUES ('aa087702-c39c-4649-a6bf-c8a726db7efc', 'Ghassem Darabi, fifth generation', 'Told by Mohammad Darabi, sixth generation.

The family''s third son was named Ghassem, and he was born in 1282 Solar Hijri (1903) in Qazvin. He too was tall and strongly built, and among his qualities were shrewdness and a cool head. From adolescence, more or less, he worked in the factory at the gut trade. He had a thorough command of it, and in his day was perhaps the leading man in the country in that work.

In 1326 (1947) he moved with his family to Tehran and took up trade there. Being inventive, capable and greatly persevering in his work, he was able to become a successful merchant. He then set about founding a factory and took up the sorting of gut, and afterwards founded a salambour works, for the processing of hides; in both of these he was very successful and became well known among his colleagues.

His wife was named Robabeh Masoudi, daughter of Haj Mirza Agha; her brothers and sisters were Ebrahim, Esmail, Mahmoud, Fatemeh and Masoumeh. In her husband''s house Robabeh was called Khanom Aziz. Of Ghassem and Robabeh six sons and two daughters remain: Kazem, Ashraf, Reza, Mohammad Taghi, Mohammad Karim, Effat, Mohammad Rahim and Nasser — and sadly Mohammad Karim, a respected and very charitable man, died in 1391 (2012).

Ghassem died of a heart attack in Farvardin 1358 (March–April 1979), at the age of seventy-five.', '٦-قاسم دارابي نسل پنجم
نقل از آقاى محمد دارابی نسل ششم
پسر سوم خانواده قاسم نام داشت كه در سال ١٢٨٢ هجرى شمسى در قزوين متولد گرديد. او نيز داراى قامتى بلند واسكلت ورزيده اى بود، هوشيارى وخونسردى از محاسن او بشمار مى رفت وتقريباً از نو جوانى در كارخانه مشغول بكار روده بوده است. در كار روده بسيار مسلط وشايد در زمان خود بالا ترين فرد در كشور محسوب مى گرديد
.
ايشان در سال ١٣٢٦ همراه خانواده اش به تهران كوچ نمود، ودر آنجا مشغول تجارت گرديد، باتوجه باينكه او فردى مبتكروتوانا وداراى پشتكار زيادى در كارخود بود، توانست به تاجرى موفق تبديل گردد. سپس او اقدام به تأسيس كارخانه نموده و به امور سرُت روده پرداخت وسپس يك كارخانه سالامبور سازى تأسيس كرد و در اين دو كار نيز بسيار موفق ودر بين همكاران خود معروف گرديد
.
همسر او ربابه مسعودى نام داشت كه دختر حاج ميرزا آقا وبرادران وخواهرانش ابراهيم، اسماعيل، محمود، فاطمه ومعصومه بوده اند، ربابه را در خانه همسرش خانم عزيز نام نهادند. از قاسم وربابه شش پسرو دودختربنامهاى كاظم، اشرف، رضا، محمدتقى، محمدكريم، عفت، محمدرحيم وناصرباقى ماندند (كه متأسفانه محمد كريم كه فردى محترم وبسيار خير بود در ١٣٩١ درگذشت). قاسم در فروردين ١٣٥٨درسن ٧٥سالگى بعلت سكته قلبى فوت مى نمايد
.', NULL, 'Tehran, Iran', '2026-08-27T08:32:46.753Z');
